// Build property prompt from webhook data
const body = $json.body || {};

const prompt = `Write a compelling real estate listing description for:

Property Type: ${body.property_type || 'House'}
Location: ${body.suburb || 'Unknown'}, ${body.city || 'South Africa'}
Price: R${body.price || '0'}
Bedrooms: ${body.bedrooms || '0'}
Bathrooms: ${body.bathrooms || '0'}
Garages: ${body.garages || '0'}
Stand Size: ${body.stand_size || '0'} sqm
Floor Size: ${body.floor_size || '0'} sqm
Features: ${body.features || 'None specified'}

Generate 3 versions:
1. LUXURY - Premium, sophisticated tone
2. FAMILY - Warm, practical, family-focused
3. INVESTMENT - ROI-focused, rental yield angle

Return as JSON:
{
  "headline": "catchy headline",
  "luxury": "description...",
  "family": "description...",
  "investment": "description...",
  "key_selling_points": ["point1", "point2", "point3"]
}`;

return [{
  json: {
    property_data: body,
    prompt: prompt
  }
}];

// Parse Groq response
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';
const propertyData = $('Build Prompt').item.json.property_data;

// Extract JSON from response
let parsed;
try {
  // Find JSON in markdown code blocks or raw
  const jsonMatch = content.match(/```json\s*([\s\S]*?)```/) || content.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : content;
  parsed = JSON.parse(jsonStr);
} catch (e) {
  // Fallback if JSON parsing fails
  parsed = {
    headline: propertyData.suburb ? `Beautiful ${propertyData.property_type} in ${propertyData.suburb}` : 'Stunning Property Available',
    luxury: content.substring(0, 500),
    family: content.substring(0, 500),
    investment: content.substring(0, 500),
    key_selling_points: ['Prime location', 'Modern features', 'Great value']
  };
}

return [{
  json: {
    property_id: propertyData.id || 'temp-' + Date.now(),
    headline: parsed.headline || 'Property Available',
    luxury_description: parsed.luxury || parsed.luxury_description || '',
    family_description: parsed.family || parsed.family_description || '',
    investment_description: parsed.investment || parsed.investment_description || '',
    key_selling_points: parsed.key_selling_points || [],
    generated_at: new Date().toISOString()
  }
}];
